"""Decide how much of an expense each person owes."""

import re

from tabtally.errors import MoneyError
from tabtally.money import allocate

WHOLE_PERCENT = re.compile(r"[0-9]+")


def split_equally(cents: int, people: list[str]) -> dict[str, int]:
    _reject_duplicates(people)
    return dict(zip(people, allocate(cents, [1] * len(people))))


def split_by_percent(cents: int, percents: list[tuple[str, int]]) -> dict[str, int]:
    people = [name for name, _ in percents]
    weights = [percent for _, percent in percents]
    _reject_duplicates(people)
    _reject_zero_percents(percents)
    if sum(weights) != 100:
        raise MoneyError(f"percentages must add up to 100, not {sum(weights)}")
    return dict(zip(people, allocate(cents, weights)))


def parse_percent(text: str) -> tuple[str, int]:
    """Turn user input such as "alice=50" into ("alice", 50)."""
    name, _, percent = text.rpartition("=")
    if not name or not WHOLE_PERCENT.fullmatch(percent):
        raise MoneyError(f"expected NAME=PERCENT with a whole number, for example alice=50: {text!r}")
    return name, int(percent)


def _reject_duplicates(people: list[str]) -> None:
    duplicates = sorted({name for name in people if people.count(name) > 1})
    if duplicates:
        raise MoneyError(f"listed more than once: {', '.join(duplicates)}")


def _reject_zero_percents(percents: list[tuple[str, int]]) -> None:
    zero = [name for name, percent in percents if percent == 0]
    if zero:
        raise MoneyError(f"percentage must be more than 0: {', '.join(zero)}")

